  public void LoadSecurityDatabase() {
    lock_guard<Object> lock = new lock_guard<Object>(mtx);
    if (FileExists(securityFile)) {
      String data = ReadRegistryFile(securityFile);
      if (!(data.isEmpty())) {
        try {
          String jsonData = XorEncryptDecrypt(data, PASSWORD);
          stringstream ss = new stringstream(jsonData);
          String line = "";
          riskDomains.clear();
          while (getline(ss, line)) {
            if ((!(line.isEmpty()) && (line.charAt(0) != '#'))) {
              riskDomains.add(line);
            }
          }
        }
        catch (exception e) {
          SetConsoleTextAttribute(hConsole, L_error);
          ((cout << "[安全核心] 解析安全文件失败: ") << e.what()) << endl;
          SetConsoleTextAttribute(hConsole, L_default);
        }
      }
    }
  }
  public boolean IsUrlSafe(String url) {
    lock_guard<Object> lock = new lock_guard<Object>(mtx);
    String domain = url;
    if ((domain.indexOf("http://") == 0)) {
      domain = domain.substring(7);
    }
    else {
      if ((domain.indexOf("https://") == 0)) {
        domain = domain.substring(8);
      }
    }
    long slashPos = domain.indexOf('/');
    if ((slashPos != string.npos)) {
      domain = domain.substring(0, slashPos);
    }
    if ((domain.indexOf("www.") == 0)) {
      domain = domain.substring(4);
    }
    for (var blockedDomain : riskDomains) {
      if (blockedDomain.isEmpty()) {
        continue;
      }
      if ((domain == blockedDomain)) {
        return false;
      }
      if ((domain.indexOf(("." + blockedDomain)) != string.npos)) {
        return false;
      }
      if (((blockedDomain[0] == '.') && (domain.indexOf(blockedDomain) != string.npos))) {
        return false;
      }
    }
    return true;
  }
  public boolean CheckUrlSafety(String url, boolean isUserSpecified) {
    if (isUserSpecified) {
      boolean safe = IsUrlSafe(url);
      if (!(safe)) {
        SetConsoleTextAttribute(hConsole, L_warning);
        ((cout << "[安全警告] 您正在访问的URL可能不安全: ") << url) << endl;
        cout << "[安全警告] 请确认是否继续 (y/n): ";
        SetConsoleTextAttribute(hConsole, L_default);
        String choice = "";
        getline(cin, choice);
        if (((choice != "y") && (choice != "Y"))) {
          LogBlockedUrl((url + " (用户拒绝)"));
          return false;
        }
        LogUserBypass(url);
        return true;
      }
      return true;
    }
    boolean safe = IsUrlSafe(url);
    if (!(safe)) {
      cout << endl;
      SetConsoleTextAttribute(hConsole, L_error);
      ((cout << "[安全核心] 拦截风险网址: ") << url) << endl;
      SetConsoleTextAttribute(hConsole, L_default);
      LogBlockedUrl(url);
      if (g_NetworkInterceptor) {
        String domain = url;
        if ((domain.indexOf("http://") == 0)) {
          domain = domain.substring(7);
        }
        else {
          if ((domain.indexOf("https://") == 0)) {
            domain = domain.substring(8);
          }
        }
        long pos = domain.indexOf('/');
        if ((pos != string.npos)) {
          domain = domain.substring(0, pos);
        }
        g_NetworkInterceptor.BlockDomain(domain, 60000);
      }
      if (g_NotifyWindow) {
        g_NotifyWindow.ShowBlockNotification("Light拦截", url);
      }
    }
    return safe;
  }
