  public static boolean CheckRemoteFileExists(String url_bin) {
    HINTERNET hSession = WinHttpOpen("Mozilla/5.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, null, null, 0);
    if (!(hSession)) {
      return false;
    }
    String host = "";
    String path = "";
    if ((url_bin.indexOf("https://") == 0)) {
      host = url_bin.substring(8);
    }
    else {
      if ((url_bin.indexOf("http://") == 0)) {
        host = url_bin.substring(7);
      }
      else {
        WinHttpCloseHandle(hSession);
        return false;
      }
    }
    long slashPos = host.indexOf('/');
    if ((slashPos != string.npos)) {
      path = host.substring(slashPos);
      host = host.substring(0, slashPos);
    }
    else {
      path = "/";
    }
    HINTERNET hConnect = WinHttpConnect(hSession, null, INTERNET_DEFAULT_HTTPS_PORT, 0);
    if (!(hConnect)) {
      WinHttpCloseHandle(hSession);
      return false;
    }
    HINTERNET hRequest = WinHttpOpenRequest(hConnect, "HEAD", null, null, null, null, WINHTTP_FLAG_SECURE);
    if (!(hRequest)) {
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return false;
    }
    if (!(WinHttpSendRequest(hRequest, null, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0))) {
      WinHttpCloseHandle(hRequest);
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return false;
    }
    if (!(WinHttpReceiveResponse(hRequest, null))) {
      WinHttpCloseHandle(hRequest);
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return false;
    }
    int statusCode = 0;
    int statusCodeSize = 0;
    boolean success = WinHttpQueryHeaders(hRequest, (WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER), null, statusCode, statusCodeSize, null);
    WinHttpCloseHandle(hRequest);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);
    return (success && ((statusCode == 200)));
  }
