  public static void printWithTilde(String text) {
    int charCount = 0;
    for (long i = 0; (i < text.length()); ) {
      char c = text.charAt(i);
      if ((c < 0x80)) {
        i += 1;
      }
      else {
        if ((c < 0xE0)) {
          i += 2;
        }
        else {
          if ((c < 0xF0)) {
            i += 3;
          }
          else {
            i += 4;
          }
        }
      }
      charCount++;
    }
    cX.clear();
    for (int i = 0; (i < charCount); i++) {
      cX += "~";
    }
  }
