  public static vector<String> ParseCommandLine(String input) {
    vector<String> result = new ArrayList<>();
    String current = "";
    boolean inQuotes = false;
    for (char c : input) {
      if ((c == '"')) {
        inQuotes = !(inQuotes);
      }
      else {
        if (((c == ' ') && !(inQuotes))) {
          if (!(current.isEmpty())) {
            result.add(current);
            current.clear();
          }
        }
        else {
          current += c;
        }
      }
    }
    if (!(current.isEmpty())) {
      result.add(current);
    }
    return result;
  }
  public static boolean IsValidFileName(String fileName) {
    if (fileName.isEmpty()) {
      return false;
    }
    char invalidChars = new char[]{'\\', '/', ':', '*', '?', '"', '<', '>', '|', '\0'};
    for (char c : fileName) {
      for (int i = 0; (invalidChars[i] != '\0'); i++) {
        if ((c == invalidChars[i])) {
          return false;
        }
      }
    }
    return true;
  }
