  public static String HttpGet(String url) {
    HINTERNET hSession = WinHttpOpen("Mozilla/5.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, null, null, 0);
    if (!(hSession)) {
      return "";
    }
    String host = "";
    String path = "";
    if ((url.indexOf("https://") == 0)) {
      host = url.substring(8);
    }
    else {
      if ((url.indexOf("http://") == 0)) {
        host = url.substring(7);
      }
      else {
        WinHttpCloseHandle(hSession);
        return "";
      }
    }
    long slashPos = host.indexOf('/');
    if ((slashPos != string.npos)) {
      path = host.substring(slashPos);
      host = host.substring(0, slashPos);
    }
    else {
      path = "/";
    }
    HINTERNET hConnect = WinHttpConnect(hSession, null, INTERNET_DEFAULT_HTTPS_PORT, 0);
    if (!(hConnect)) {
      WinHttpCloseHandle(hSession);
      return "";
    }
    HINTERNET hRequest = WinHttpOpenRequest(hConnect, "GET", null, null, null, null, WINHTTP_FLAG_SECURE);
    if (!(hRequest)) {
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return "";
    }
    String headers = "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36\r\n";
    if (!(WinHttpSendRequest(hRequest, null, headers.length(), WINHTTP_NO_REQUEST_DATA, 0, 0, 0))) {
      WinHttpCloseHandle(hRequest);
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return "";
    }
    if (!(WinHttpReceiveResponse(hRequest, null))) {
      WinHttpCloseHandle(hRequest);
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      return "";
    }
    String response = "";
    int bytesRead = 0;
    char buffer = '\0';
    while ((WinHttpReadData(hRequest, buffer, (0 - 1), bytesRead) && (bytesRead > 0))) {
      buffer[bytesRead] = '\0';
      response += buffer;
    }
    WinHttpCloseHandle(hRequest);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);
    return response;
  }
