      (cout << "错误：请指定要解锁的文件夹路径！") << endl;
      (cout << "用法: Unlock <文件夹路径>") << endl;
      (cout << "示例: Unlock C:\\Program Files\\.light") << endl;
      SetConsoleTextAttribute(hConsole, L_default);
