    String resolvedXzyx = ResolvePath(xzyxFile);
    String resolvedOutDir = ResolvePath(outDir);
    SetConsoleTextAttribute(hConsole, L_default);
    ((((cout << "开始解压: ") << resolvedXzyx) << " -> ") << resolvedOutDir) << endl;
