  public static boolean ExtractZipWithMinizip(String zipPath, String destDir) {
    unzFile zipFile = unzOpen(null);
    if (!(zipFile)) {
      System.err.println("无法打开 ZIP 文件: " + zipPath);
      return false;
    }
    CreateDirectoryA(null, null);
    unz_global_info globalInfo = null;
    if ((unzGetGlobalInfo(zipFile, globalInfo) != UNZ_OK)) {
      System.err.println("获取 ZIP 信息失败");
      unzClose(zipFile);
      return false;
    }
    for (uLong i = 0; (i < globalInfo.number_entry); i++) {
      unz_file_info fileInfo = null;
      char filename = new char[]{0};
      if ((unzGetCurrentFileInfo(zipFile, fileInfo, filename, 0, null, 0, null, 0) != UNZ_OK)) {
        System.err.println("获取文件信息失败");
        break;
      }
      String entryName = filename;
      String outputPath = ((destDir + "\\") + entryName);
      if (((entryName.back() == '/') || (entryName.back() == '\\'))) {
        CreateDirectoryA(null, null);
      }
      else {
        String parentDir = outputPath;
        long lastSlash = parentDir.find_last_of("\\/");
        if ((lastSlash != string.npos)) {
          parentDir = parentDir.substring(0, lastSlash);
          if (!(parentDir.isEmpty())) {
            error_code ec = null;
            fs.create_directories(fs.path(parentDir), ec);
            if (ec) {
              System.err.println("创建解压目录失败: " + parentDir + ", error=" + ec.message());
              unzCloseCurrentFile(zipFile);
              if ((i < (globalInfo.number_entry - 1))) {
                unzGoToNextFile(zipFile);
              }
              continue;
            }
          }
        }
        if ((unzOpenCurrentFile(zipFile) == UNZ_OK)) {
          FILE outputFile = fopen(null, "wb");
          if (outputFile) {
            char buffer = '\0';
            int bytesRead = 0;
            boolean writeOk = true;
            while ((((bytesRead = unzReadCurrentFile(zipFile, buffer, 0))) > 0)) {
              if ((fwrite(buffer, 1, bytesRead, outputFile) != ((long) bytesRead))) {
                writeOk = false;
                break;
              }
            }
            if ((bytesRead < 0)) {
              writeOk = false;
            }
            fclose(outputFile);
            if (!(writeOk)) {
              System.err.println("写入解压文件失败: " + outputPath);
              unzCloseCurrentFile(zipFile);
              if ((i < (globalInfo.number_entry - 1))) {
                unzGoToNextFile(zipFile);
              }
              continue;
            }
          }
          unzCloseCurrentFile(zipFile);
        }
      }
      if ((i < (globalInfo.number_entry - 1))) {
        if ((unzGoToNextFile(zipFile) != UNZ_OK)) {
          break;
        }
      }
    }
    unzClose(zipFile);
    return true;
  }
  public static boolean DeleteFileSecure(String filePath) {
    int attributes = GetFileAttributesA(null);
    if ((attributes != INVALID_FILE_ATTRIBUTES)) {
      SetFileAttributesA(null, (attributes & ~(FILE_ATTRIBUTE_READONLY)));
    }
    if (DeleteFileA(null)) {
      return true;
    }
    for (int i = 0; (i < 5); i++) {
      Sleep(100);
      if (DeleteFileA(null)) {
        return true;
      }
    }
    return false;
  }
