  public static vector<FileLinkInfo> FilterAndRankFileLinks(vector<AnchorLink> links) {
    vector<FileLinkInfo> infos = new ArrayList<>();
    int filteredBySystem = 0;
    for (var anchor : links) {
      String url = DecodeBingRedirectUrl(anchor.url);
      if (((url.indexOf("http://") != 0) && (url.indexOf("https://") != 0))) {
        continue;
      }
      String fileName = ExtractFileNameFromUrl(url);
      String displayName = (anchor.text.isEmpty() ? fileName : anchor.text);
      String nameForScore = ToLowerAscii(((displayName + " ") + url));
      int score = ScorePackageForSystem(nameForScore);
      if ((score < 0)) {
        filteredBySystem++;
        SetConsoleTextAttribute(hConsole, L_warning);
        ((((((cout << "[系统过滤] 跳过不适配当前系统(") << GetNativeSystemArch()) << ")的文件: ") << displayName) << "  <-  ") << url) << endl;
        SetConsoleTextAttribute(hConsole, L_default);
        continue;
      }
      FileLinkInfo info = new FileLinkInfo();
      info.url = url;
      info.fileName = fileName;
      info.displayName = (displayName.isEmpty() ? url : displayName);
      info.systemScore = score;
      info.isInstaller = IsInstallerPackageFile(nameForScore);
      infos.add(info);
    }
    vector<FileLinkInfo> result = new ArrayList<>();
    map<String, Long> indexByKey = new HashMap<>();
    int removedDuplicates = 0;
    for (var info : infos) {
      String key = (IsFileExtensionUrl(info.url) ? ToLowerAscii(info.fileName) : ToLowerAscii(info.displayName));
      var it = indexByKey.containsKey(key);
      if ((it == indexByKey.end())) {
        indexByKey.put(key, result.size());
        result.add(info);
      }
      else {
        long idx = it.second;
        removedDuplicates++;
        if ((info.systemScore > result.get(idx).systemScore)) {
          SetConsoleTextAttribute(hConsole, L_warning);
          (((((cout << "[同名去重] 文件 \"") << info.displayName) << "\" 有多个下载链接，") << "移除适配度较低的: ") << result.get(idx).url) << endl;
          SetConsoleTextAttribute(hConsole, L_default);
          result.set(idx, info);
        }
        else {
          SetConsoleTextAttribute(hConsole, L_warning);
          (((((cout << "[同名去重] 已移除同名文件链接: ") << info.url) << "  (文件名: ") << info.displayName) << ")") << endl;
          SetConsoleTextAttribute(hConsole, L_default);
        }
      }
    }
    stable_sort(result.begin(), result.end(), (FileLinkInfo a, FileLinkInfo b) -> {      return (a.systemScore > b.systemScore);      });
    if (((filteredBySystem > 0) || (removedDuplicates > 0))) {
      SetConsoleTextAttribute(hConsole, L_default);
      (((((((((cout << "[信息] 已按系统类型(") << GetNativeSystemArch()) << ")过滤 ") << filteredBySystem) << " 个不适配链接，去除 ") << removedDuplicates) << " 个同名文件链接，剩余 ") << result.size()) << " 个可用链接") << endl;
    }
    return result;
  }
