  public static boolean DownloadFileWithProgressMulti(String url, String savePath) {
    long fileSize = GetFileSizeFromURL(url);
    if ((fileSize <= 0)) {
      return DownloadFileWithProgressSingle(url, savePath);
    }
    long hFile = CreateFileA(null, 0x40000000, 0x00000002, null, 2, FILE_ATTRIBUTE_NORMAL, null);
    if ((hFile == -(1))) {
      return false;
    }
    CloseHandle(hFile);
    int threadCount = 4;
    if ((fileSize < ((10 * 1024) * 1024))) {
      threadCount = 2;
    }
    else {
      if ((fileSize < ((50 * 1024) * 1024))) {
        threadCount = 4;
      }
      else {
        threadCount = 8;
      }
    }
    long chunkSize = (fileSize / threadCount);
    vector<Thread> threads = new ArrayList<>();
    long totalDownloaded = (0);
    for (int i = 0; (i < threadCount); i++) {
      long start = (i * chunkSize);
      long end = (((i == (threadCount - 1))) ? (fileSize - 1) : ((((i + 1)) * chunkSize) - 1));
      threads.add(thread(() -> {        DownloadChunk(url, savePath, start, end, ref(totalDownloaded));        }));
    }
    int lastPercent = -(1);
    while (true) {
      long current = totalDownloaded.load();
      if ((current > fileSize)) {
        current = fileSize;
      }
      int currentPercent = ((int) ((((current * 100)) / fileSize)));
      if ((currentPercent > 100)) {
        currentPercent = 100;
      }
      if ((currentPercent != lastPercent)) {
        lastPercent = currentPercent;
        (((cout << "\r下载进度: ") << currentPercent) << "%") << flush;
      }
      if ((currentPercent >= 100)) {
        break;
      }
      Sleep(500);
    }
    for (var t : threads) {
      if (t.joinable()) {
        t.join();
      }
    }
    (cout << "\r下载完成!                  ") << endl;
    return true;
  }
