  public static boolean ResolveCommandFile(String command, String currentDir, String outPath, String outArgs) {
    String text = TrimCopy(command);
    if (text.isEmpty()) {
      return false;
    }
    String token = "";
    long pos = 0;
    if ((text.charAt(0) == '"')) {
      long end = text.indexOf('"', 1);
      if ((end == string.npos)) {
        return false;
      }
      token = text.substring(1, (end - 1));
      pos = (end + 1);
    }
    else {
      long end = text.find_first_of(" \t");
      token = (((end == string.npos)) ? text : text.substring(0, end));
      pos = (((end == string.npos)) ? text.length() : end);
    }
    outArgs = TrimCopy(text.substring(pos));
    if (token.isEmpty()) {
      return false;
    }
    String baseDir = currentDir;
    if (baseDir.isEmpty()) {
      baseDir = ".";
    }
    ArrayList<String> candidates = new ArrayList<>();
    var addCandidate = (String name) -> {      if (name.isEmpty()) {
        return;
      }
      boolean absolute = (((((name.length() >= 2) && (name.charAt(1) == ':'))) || ((((name.length() >= 2) && (name.charAt(0) == '\\')) && (name.charAt(1) == '\\')))) || ((!(name.isEmpty()) && (name.charAt(0) == '\\'))));
      String full = (absolute ? name : (((baseDir + "\\") + name)));
      int attr = GetFileAttributesA(null);
      if (((attr != INVALID_FILE_ATTRIBUTES) && !(((attr & FILE_ATTRIBUTE_DIRECTORY))))) {
        candidates.add(full);
      }        };
    addCandidate(token);
    if ((token.indexOf('.') == string.npos)) {
      String pathext = getenv("PATHEXT");
      String exts = (pathext ? pathext : ".COM;.EXE;.BAT;.CMD");
      stringstream ss = new stringstream(exts);
      String ext = "";
      while (null) {
        if (!(ext.isEmpty())) {
          addCandidate((token + ext));
        }
      }
      addCandidate((token + ".bat"));
      addCandidate((token + ".cmd"));
      addCandidate((token + ".exe"));
    }
    if (candidates.isEmpty()) {
      return false;
    }
    outPath = candidates.get(0);
    return true;
  }
